def ref(path, needle=None):
    p = ROOT / path
    assert p.is_file(), path
    n = 1
    if needle:
        hits = [i for i, line in enumerate(p.read_text().splitlines(), 1) if needle in line]
        assert hits, (path, needle)
        n = hits[0]
    return {'file': path, 'line': n}


def cite(r):
    path = r['file']
    return f"[{path}:{r['line']}](../{path}#L{r['line']})"


