def table(headers,rows):
    def cell(x): return str(x).replace('|','\\|').replace('\n','<br>')
    return '\n'.join(['| '+' | '.join(headers)+' |','| '+' | '.join(['---']*len(headers))+' |',*['| '+' | '.join(cell(x) for x in row)+' |' for row in rows]])

tables = {
'personas':table(['User','Problem','Can do today','Expected but unavailable','Expectation risk'],personas),
'use_cases':table(['Use case','Class','Current scope'],use_cases),
'workflow':table(['Step','User intent','UI surface','Backend/local operation','Artifact/state','Next action','Prerequisite / friction'],workflow),
 'tools':table(['Tool','Role','Reason / risk'],tools),
 'terms':table(['Term','Meaning','Consistency finding'],terms),
 'commercial':table(['Capability','Status','Evidence-supported gap'],commercial),
 'feedback':table(['Feedback supplied','Class','Audit interpretation'],feedback),
 'screenshots':table(['Inspected image','What a newcomer learns','Story/freshness finding'],screenshots),
 'scientific_debt':table(['Item','State','Evidence boundary','Evidence','Impact'],[[a,b,c,cite(E[d]),e] for a,b,c,d,e in scientific_debt]),
 'findings':table(['ID / severity','Category / finding','Evidence','User impact','Blocks current use?','Soon? / later action'],[[f"{x['id']} / {x['severity']} ({x['priority']})",x['category']+': '+x['title'],'; '.join(cite(E[k]) for k in x['evidence']),x['impact'],x['blocks_current_use'],str(x['fix_soon'])+'; '+x['action']] for x in findings]),
 'options':table(['Rank / initiative','Benefit / evidence','Cost','Risk','Dependency','Success'],[[str(x['rank'])+' / '+x['initiative'],x['benefit']+' Evidence: '+', '.join(x['evidence']),x['cost'],x['risk'],x['dependency'],x['success']] for x in options]),
 'scorecard':table(['Dimension','Score 1–5','Rationale'],scorecard),
 'source_groups':table(['Frozen group','Files','SHA256'],[[k,v['count'],v['sha256']] for k,v in LOCK['source_groups'].items()]),
 'claims':table(['ID / Claim','Current wording/location','Level','Supported?','Qualification needed','Recommended wording / evidence'],[[x['id']+' / '+x['claim'],x['current_wording_location'],x['evidence_level'],x['supported'],x['qualification_needed'],x['recommended_wording']+' '+ '; '.join(cite(r) for r in x['evidence'])] for x in claims]),
}

